-- The Fiverr alternatives guide went live with the template's blanks still in it ("[price]",
-- "[best for]"). This fills them from each platform's public pages, checked 2026-11-05, and puts it
-- back in the Alternatives category for its disclosure. Skips the guide if it's been fixed by hand.

begin;

update guides set
  body_json = $guide${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fiverr is a quick way to find a video editor for a single job. If you need someone for a YouTube channel week after week, these five options are worth comparing first. "},{"type":"text","text":"We compared them on how they check people, how fees work and how well they fit regular YouTube work."}]},{"type":"directoryStats","attrs":{"service":"youtube-video-production-agencies"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The short list"}]},{"type":"comparisonTable","attrs":{"rows":[{"name":"YT Agencies","bestFor":"Ongoing YouTube work with a specialist team","price":"Free to compare","difference":"Agencies that focus on YouTube, compared side by side","anchor":"yt-agencies"},{"name":"Upwork","bestFor":"Comparing proposals for a regular editor","price":"3–5% fee + contract fee","difference":"Post a job and hire by the hour or at a fixed price","anchor":"upwork"},{"name":"Contra","bestFor":"Choosing an editor by portfolio","price":"No freelancer commission; client fees vary","difference":"Browse profiles and send a contract, with no job post","anchor":"contra"},{"name":"Toptal","bestFor":"Bigger budgets that want a screened editor","price":"Custom quote","difference":"A talent matcher finds the editor, with a trial of up to two weeks","anchor":"toptal"},{"name":"PeoplePerHour","bestFor":"Small, clearly defined projects","price":"£0.60 + 10% per card or PayPal payment","difference":"Post a project or buy a fixed-price offer","anchor":"peopleperhour"}],"highlightFirst":true}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How we picked these"}]},{"type":"paragraph","content":[{"type":"text","text":"We read each platform's public pricing and how-it-works pages, then looked at vetting, the pricing model and whether it suits regular YouTube work. This isn't a hands-on test: we didn't hire an editor on each platform. Fees change, so check the total at checkout before you pay."}]},{"type":"productCard","attrs":{"badge":"BEST FOR YOUTUBE SPECIALISTS","title":"YT Agencies","description":"A directory of YouTube agencies, not freelancers. You compare agencies by service, niche and starting price, then send one request and hear back from agencies that do this work.\n\nIt's our product, so we list it first and say so.","points":[{"kind":"good","text":"Free for businesses and creators to compare and send requests"},{"kind":"good","text":"Profiles show starting prices, services and the niches each agency works in"},{"kind":"good","text":"Verified badges are earned through checks and can't be bought"},{"kind":"caveat","text":"Agencies, not solo editors: usually a bigger commitment than a one-off gig"}],"image":"","imageAlt":"","caption":"","price":"Free for businesses and creators","priceSource":"","ctaLabel":"Browse agencies","ctaHref":"/agencies","chooseIf":"you want a team that handles YouTube editing as part of ongoing channel work.","ours":true}},{"type":"productCard","attrs":{"badge":"BEST FOR COMPARING PROPOSALS","title":"Upwork","description":"A large freelance marketplace. You post a job or invite people, then hire an editor by the hour or at a fixed price.","points":[{"kind":"good","text":"Hourly and fixed-price contracts, so it can fit regular work as well as single jobs"},{"kind":"good","text":"Editors come to you with proposals, so you can compare several at once"},{"kind":"caveat","text":"You do the vetting yourself, and the fee depends on your plan and how you pay"}],"image":"","imageAlt":"","caption":"","price":"3–5% marketplace fee on the Basic plan, plus a one-time contract fee of $0.99–$14.99","priceSource":"https://www.upwork.com/pricing/client","ctaLabel":"","ctaHref":"","chooseIf":"you want to compare several editors and manage the work yourself.","ours":false}},{"type":"productCard","attrs":{"badge":"BEST FOR BROWSING PORTFOLIOS","title":"Contra","description":"A platform where freelancers show their work on portfolio profiles. You can browse editors and send a contract without posting a job.","points":[{"kind":"good","text":"Freelancers pay no commission on what they earn"},{"kind":"good","text":"No job post needed: review portfolios and contact who you like"},{"kind":"caveat","text":"Client fees depend on the project, so check the pricing page before you start"}],"image":"","imageAlt":"","caption":"","price":"No commission for freelancers. Clients can pay a flat fee on larger payments, plus card processing","priceSource":"https://contra.com/pricing","ctaLabel":"","ctaHref":"","chooseIf":"you'd rather pick an editor by their past work than sort through proposals.","ours":false}},{"type":"productCard","attrs":{"badge":"BEST FOR A SCREENED EDITOR","title":"Toptal","description":"A talent network that screens freelancers and matches you with one. Toptal says fewer than 3% of applicants are accepted.","points":[{"kind":"good","text":"Screening and matching are done for you"},{"kind":"good","text":"Each engagement starts with a trial of up to two weeks, and you aren't billed if you're not satisfied"},{"kind":"caveat","text":"The price depends on seniority and commitment, and you can't see it until you talk to them"}],"image":"","imageAlt":"","caption":"","price":"No public price list: a talent matcher gives you an estimate","priceSource":"https://www.toptal.com/marketing/video-editors","ctaLabel":"","ctaHref":"","chooseIf":"you have a bigger budget and would rather pay for someone else to do the screening.","ours":false}},{"type":"productCard","attrs":{"badge":"BEST FOR SMALL PROJECTS","title":"PeoplePerHour","description":"A freelance marketplace where you can post a project for proposals or buy a fixed-price offer from a freelancer.","points":[{"kind":"good","text":"Fixed-price offers make a small, clear job easy to buy"},{"kind":"good","text":"You can also post a project and compare proposals"},{"kind":"caveat","text":"The buyer fee is charged per payment, so many small payments cost more"}],"image":"","imageAlt":"","caption":"","price":"£0.60 + 10% buyer fee per card or PayPal payment, per its support page","priceSource":"https://support.peopleperhour.com/hc/en-us/articles/205217197-PPH-Fees","ctaLabel":"","ctaHref":"","chooseIf":"you have a small, clearly defined edit and don't need the same person every week.","ours":false}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fiverr vs YT Agencies"}]},{"type":"abTable","attrs":{"aLabel":"Fiverr","bLabel":"YT Agencies","rows":[{"label":"Who you hire","a":"Individual freelancers","b":"Agencies"},{"label":"Pricing","a":"Fixed-price packages set by each seller","b":"Free to compare; agencies set their own prices"},{"label":"Best for","a":"One-off edits","b":"Ongoing channel work"},{"label":"Fees","a":"5.5% service fee, plus $3.50 on orders under $200","b":"No fee for businesses and creators"}],"bBetter":"You need the same team every week, want strategy as well as editing, or care about a track record on YouTube specifically."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hiring on a marketplace: what to expect"}]},{"type":"prosCons","attrs":{"good":["Fast to find someone for a small job","Easy to compare portfolios","Clear prices on fixed packages"],"watch":["Quality varies a lot between sellers","Fees can add up on long projects","A new editor means explaining your channel's style again"]}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Frequently asked questions"}]},{"type":"faq","attrs":{"items":[{"q":"Is YT Agencies free?","a":"Yes, for businesses and creators. Agencies can pay for a Pro plan; Pro agencies are shown first and always marked with a Pro badge."},{"q":"How much does a YouTube editor cost on these platforms?","a":"Each editor sets their own price, and the platform adds its fee. As of November 5, 2026: Upwork charges 3–5% on its Basic plan plus a one-time contract fee, PeoplePerHour lists £0.60 + 10% per card or PayPal payment, and Fiverr charges 5.5% plus $3.50 on orders under $200. Contra charges freelancers no commission, and Toptal gives you a quote."},{"q":"Freelancer or agency: which should I hire?","a":"A freelancer usually costs less and suits editing alone, but you handle the briefs, the feedback and the backup if they're busy. An agency costs more and can take on strategy, thumbnails and publishing as well, with a team behind the work. If you only need clean edits, start with a freelancer. If you want someone responsible for how the channel grows, compare agencies."}]}},{"type":"ctaBox","attrs":{"variant":"box","heading":"Compare YouTube agencies that edit for channels like yours","lines":["See starting prices and the niches each agency works in.","Free for businesses and creators."],"primaryLabel":"Browse agencies","primaryHref":"/agencies","secondaryLabel":"Request proposals","secondaryHref":"/request-proposals"}},{"type":"paragraph","content":[{"type":"text","text":"Read more: "},{"type":"text","text":"how much a YouTube agency costs","marks":[{"type":"link","attrs":{"href":"/guides"}}]},{"type":"text","text":"."}]}]}$guide$::jsonb,
  body_html = $guide$<p>Fiverr is a quick way to find a video editor for a single job. If you need someone for a YouTube channel week after week, these five options are worth comparing first. We compared them on how they check people, how fees work and how well they fit regular YouTube work.</p><div data-block="directoryStats"></div><h2>The short list</h2><div data-block="comparisonTable"><p>YT Agencies Ongoing YouTube work with a specialist team Free to compare Agencies that focus on YouTube, compared side by side Upwork Comparing proposals for a regular editor 3–5% fee + contract fee Post a job and hire by the hour or at a fixed price Contra Choosing an editor by portfolio No freelancer commission; client fees vary Browse profiles and send a contract, with no job post Toptal Bigger budgets that want a screened editor Custom quote A talent matcher finds the editor, with a trial of up to two weeks PeoplePerHour Small, clearly defined projects £0.60 + 10% per card or PayPal payment Post a project or buy a fixed-price offer</p></div><h2>How we picked these</h2><p>We read each platform's public pricing and how-it-works pages, then looked at vetting, the pricing model and whether it suits regular YouTube work. This isn't a hands-on test: we didn't hire an editor on each platform. Fees change, so check the total at checkout before you pay.</p><div data-block="productCard"><p>BEST FOR YOUTUBE SPECIALISTS YT Agencies A directory of YouTube agencies, not freelancers. You compare agencies by service, niche and starting price, then send one request and hear back from agencies that do this work.

It's our product, so we list it first and say so. Free for businesses and creators to compare and send requests Profiles show starting prices, services and the niches each agency works in Verified badges are earned through checks and can't be bought Agencies, not solo editors: usually a bigger commitment than a one-off gig Free for businesses and creators you want a team that handles YouTube editing as part of ongoing channel work.</p></div><div data-block="productCard"><p>BEST FOR COMPARING PROPOSALS Upwork A large freelance marketplace. You post a job or invite people, then hire an editor by the hour or at a fixed price. Hourly and fixed-price contracts, so it can fit regular work as well as single jobs Editors come to you with proposals, so you can compare several at once You do the vetting yourself, and the fee depends on your plan and how you pay 3–5% marketplace fee on the Basic plan, plus a one-time contract fee of $0.99–$14.99 you want to compare several editors and manage the work yourself.</p></div><div data-block="productCard"><p>BEST FOR BROWSING PORTFOLIOS Contra A platform where freelancers show their work on portfolio profiles. You can browse editors and send a contract without posting a job. Freelancers pay no commission on what they earn No job post needed: review portfolios and contact who you like Client fees depend on the project, so check the pricing page before you start No commission for freelancers. Clients can pay a flat fee on larger payments, plus card processing you'd rather pick an editor by their past work than sort through proposals.</p></div><div data-block="productCard"><p>BEST FOR A SCREENED EDITOR Toptal A talent network that screens freelancers and matches you with one. Toptal says fewer than 3% of applicants are accepted. Screening and matching are done for you Each engagement starts with a trial of up to two weeks, and you aren't billed if you're not satisfied The price depends on seniority and commitment, and you can't see it until you talk to them No public price list: a talent matcher gives you an estimate you have a bigger budget and would rather pay for someone else to do the screening.</p></div><div data-block="productCard"><p>BEST FOR SMALL PROJECTS PeoplePerHour A freelance marketplace where you can post a project for proposals or buy a fixed-price offer from a freelancer. Fixed-price offers make a small, clear job easy to buy You can also post a project and compare proposals The buyer fee is charged per payment, so many small payments cost more £0.60 + 10% buyer fee per card or PayPal payment, per its support page you have a small, clearly defined edit and don't need the same person every week.</p></div><h2>Fiverr vs YT Agencies</h2><div data-block="abTable"><p>Fiverr YT Agencies Who you hire Individual freelancers Agencies Pricing Fixed-price packages set by each seller Free to compare; agencies set their own prices Best for One-off edits Ongoing channel work Fees 5.5% service fee, plus $3.50 on orders under $200 No fee for businesses and creators You need the same team every week, want strategy as well as editing, or care about a track record on YouTube specifically.</p></div><h2>Hiring on a marketplace: what to expect</h2><div data-block="prosCons"><p>Fast to find someone for a small job Easy to compare portfolios Clear prices on fixed packages Quality varies a lot between sellers Fees can add up on long projects A new editor means explaining your channel's style again</p></div><h2>Frequently asked questions</h2><div data-block="faq"><p>Is YT Agencies free? Yes, for businesses and creators. Agencies can pay for a Pro plan; Pro agencies are shown first and always marked with a Pro badge. How much does a YouTube editor cost on these platforms? Each editor sets their own price, and the platform adds its fee. As of November 5, 2026: Upwork charges 3–5% on its Basic plan plus a one-time contract fee, PeoplePerHour lists £0.60 + 10% per card or PayPal payment, and Fiverr charges 5.5% plus $3.50 on orders under $200. Contra charges freelancers no commission, and Toptal gives you a quote. Freelancer or agency: which should I hire? A freelancer usually costs less and suits editing alone, but you handle the briefs, the feedback and the backup if they're busy. An agency costs more and can take on strategy, thumbnails and publishing as well, with a team behind the work. If you only need clean edits, start with a freelancer. If you want someone responsible for how the channel grows, compare agencies.</p></div><div data-block="ctaBox"><p>Compare YouTube agencies that edit for channels like yours See starting prices and the niches each agency works in. Free for businesses and creators.</p></div><p>Read more: <a href="/guides">how much a YouTube agency costs</a>.</p>$guide$,
  seo_description = $guide$Five places to hire a YouTube editor instead of Fiverr: Upwork, Contra, Toptal, PeoplePerHour and YouTube agencies, compared by fees and fit.$guide$,
  prices_checked_on = '2026-11-05',
  category_id = coalesce((select id from guide_categories where slug = 'alternatives'), category_id),
  author_id = coalesce(author_id, (select id from authors where slug = 'whywaris')),
  content_updated_at = now()
where slug = 'fiverr-alternatives' and body_json::text like '%[best for]%';

commit;
